def retirar(saldo, quantidade):
    if type(quantidade) is not int or quantidade <= 0:
        return {"ok": False, "saldo": saldo}
    if quantidade > saldo:
        return {"ok": False, "saldo": saldo}
    return {"ok": True, "saldo": saldo - quantidade}

