print(buscar_ordenado(valores, 9))
print(buscar_ordenado(valores, 0))

def visitas_simples(n):
    total = 0
    for i in range(n):
        total += 1
    return total

def pares_completos(n):
    total = 0
    for i in range(n):
        for j in range(n):
            total += 1
    return total

