def confirmar(estado):
    if estado["status"] == "confirmada":
        return estado.copy()
    if estado["status"] != "aberta":
        return estado.copy()
    if estado["quantidade"] > estado["saldo"]:
        return estado.copy()
    novo = estado.copy()
    novo["saldo"] -= novo["quantidade"]
    novo["status"] = "confirmada"
    return novo

