def confirmar(estado, id_ordem):
    ordem = estado["ordens"].get(id_ordem)
    if ordem is None:
        return "ordem ausente"
    if ordem["status"] == "confirmada":
        return "já confirmada"
    if ordem["status"] != "aberta":
        return "status inválido"
    quantidade = ordem["quantidade"]
    if type(quantidade) is not int or quantidade <= 0:
        return "quantidade inválida"
    item = ordem["item"]
    if item not in estado["saldos"]:
        return "item ausente"
    saldo = estado["saldos"][item]
    if quantidade > saldo:
        return "material insuficiente"
    estado["saldos"][item] = saldo - quantidade
    ordem["status"] = "confirmada"
    return "confirmada"

